    mockMvc.perform(post("/api/releases/1/expand").contentType("application/json").content("""
                    {"requestId":"r4","expectedVersion":2,"ratio":20}
                    """))
            .andExpect(status().isConflict())
            .andExpect(jsonPath("$.code").value("RATIO_DECREASE"));

