            .andExpect(status().isConflict())
            .andExpect(jsonPath("$.code").value("RELEASE_NOT_ACTIVE"));

    // 取消不存在的发布单：404
    mockMvc.perform(post("/api/releases/9999/cancel").contentType("application/json")
                    .content("{\"requestId\":\"r10\"}"))
            .andExpect(status().isNotFound());
}

